  if(!w||!pick){ arr.push('桌案空了。'); return {place:'帅帐',text:function(){return arr;},options:[{t:'离开',go:'v65_warPanel'}]}; }
  var r=window.v655_negotiateRoll(w,pick.terms);
  arr.push('你开的条件：'+(pick.note||''));
